 page=pages[P+'lab/'];text=page['html'];a=text.index('<form id="budget-form">');b=text.index('</form>',a);form=text[a:b];dust=re.search(r'<label>Stardust available.*?</label>',form).group();total=re.search(r'<p id="budget-total".*?</p>',form).group();reset='<button type="reset">Reset budget</button>';form=form.replace(dust,'').replace(total,'').replace(reset,'');form=form.replace('<form id="budget-form">','<form id="budget-form"><div class="budget-editor">',1);form+='</div><aside class="budget-summary" aria-label="Budget summary"><h3>Your Lab budget</h3>'+dust+total+reset+'<p>Hidden selections stay in the total. Prices are a dated snapshot, not a live checkout.</p></aside>';page['html']=text[:a]+form+text[b:]
